package com.example.fitapp.common;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.Transient;
import jakarta.persistence.Version;
import java.time.Instant;
import java.util.UUID;

/**
 * Shared columns of every user-owned, synced table. IDs are generated by the client.
 *
 * <p>Two clocks: {@code updatedAt} is the editing device's clock and decides last-write-wins;
 * {@code syncedAt} is the server's clock, set on every write, and is what clients pull by.
 */
@MappedSuperclass
public abstract class SyncableEntity {

    @Id
    @Column(nullable = false, updatable = false)
    private UUID id;

    @Column(name = "user_id", nullable = false, updatable = false)
    private UUID userId;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Column(name = "synced_at", nullable = false)
    private Instant syncedAt;

    @Column(name = "deleted_at")
    private Instant deletedAt;

    @Version
    @Column(nullable = false)
    private Long version;

    /** Set by sync when updatedAt carries the client's timestamp that must survive the save. */
    @Transient private boolean clientTimestamp;

    protected SyncableEntity() {}

    protected SyncableEntity(UUID id, UUID userId) {
        this.id = id;
        this.userId = userId;
    }

    @PrePersist
    void onCreate() {
        Instant now = Instant.now();
        if (createdAt == null) {
            createdAt = now;
        }
        if (updatedAt == null) {
            updatedAt = now;
        }
        syncedAt = now;
        clientTimestamp = false;
    }

    @PreUpdate
    void onUpdate() {
        Instant now = Instant.now();
        if (!clientTimestamp) {
            updatedAt = now;
        }
        clientTimestamp = false;
        syncedAt = now;
    }

    /** Applies a client-supplied edit time (used by sync) instead of stamping the server clock. */
    public void setClientUpdatedAt(Instant when) {
        this.updatedAt = when;
        this.clientTimestamp = true;
    }

    public UUID getId() {
        return id;
    }

    public UUID getUserId() {
        return userId;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public Instant getSyncedAt() {
        return syncedAt;
    }

    public Instant getDeletedAt() {
        return deletedAt;
    }

    public void setDeletedAt(Instant deletedAt) {
        this.deletedAt = deletedAt;
    }

    public Long getVersion() {
        return version;
    }
}
